    '<strong>%s</strong> bulk QR codes Limit' => '<strong>%s</strong> Limite de codes QR groupés',
    'That action is not available for the selected demo right now.' => 'Cette action n’est pas disponible pour la démo sélectionnée pour le moment.',
    '302 Temporary redirect' => '302 Redirection temporaire',
